        if (memcmp(c_got, c_exp, sizeof(c_got)) != 0) {
            fprintf(stderr, "c buffer mismatch\n");
            return 1;
        }
    }
    return 0;
}

int main(void) {
    int rc = nonbenchmark_correctness_main();
    printf("{ \"correctness\": %s }\n", rc == 0 ? "1" : "0");
    return 0;
}
